"""Algorithm B: empirical entropy and the partition-function form of the Shtarkov sum.

For a word x and a k-state automaton M, the empirical state-conditional entropy is

    Hhat_M(x) = sum_s (a_s + b_s) * h(a_s / (a_s + b_s)),   h(p) = -p log p - (1-p) log(1-p),

where (a_s, b_s) are the per-state counts of 1s and 0s emitted by M while reading x.
The maximised likelihood of x equals exp(-Hhat_M(x)) exactly, so

    S_n(M) = sum_x exp(-Hhat_M(x)),

a partition function over the 2^n words with empirical entropy as the energy.  The
counting bound then reads as a Kraft-type inequality:

    sum_x exp(-Hhat_M(x)) <= ((n+1)^2)^k,        0 <= Hhat_M(x) <= n log 2.

Complexity: Theta(n + k) per word for the entropy; Theta(2^n (n+k)) for the full
partition function by enumeration (use the count-fibre dynamic program for large n).
"""

from __future__ import annotations

import itertools
import math
from typing import Iterator, List, Sequence, Tuple

Word = Tuple[int, ...]


def binary_entropy(p: float) -> float:
    """Binary entropy h(p) in nats, with h(0) = h(1) = 0 by continuity."""
    if p <= 0.0 or p >= 1.0:
        return 0.0
    return -p * math.log(p) - (1.0 - p) * math.log(1.0 - p)


def state_counts(step: Sequence[Sequence[int]], init: int, x: Word) -> List[Tuple[int, int]]:
    """Per-state emission counts (a_s, b_s) accumulated while reading x."""
    k = len(step)
    a = [0] * k
    b = [0] * k
    s = init
    for sym in x:
        if sym:
            a[s] += 1
        else:
            b[s] += 1
        s = step[s][sym]
    return list(zip(a, b))


def empirical_entropy(step: Sequence[Sequence[int]], init: int, x: Word) -> float:
    """Hhat_M(x), in nats."""
    total = 0.0
    for a, b in state_counts(step, init, x):
        if a + b:
            total += (a + b) * binary_entropy(a / (a + b))
    return total


def all_words(n: int) -> Iterator[Word]:
    """All 2^n binary words of length n."""
    return itertools.product((0, 1), repeat=n)


def partition_function(step: Sequence[Sequence[int]], init: int, n: int) -> float:
    """S_n(M) = sum_x exp(-Hhat_M(x))."""
    return sum(math.exp(-empirical_entropy(step, init, x)) for x in all_words(n))


def kraft_slack(step: Sequence[Sequence[int]], init: int, n: int) -> float:
    """Excess over the Kraft budget, in nats: log(sum_x e^{-Hhat}) — bounded by 2k log(n+1)."""
    return math.log(partition_function(step, init, n))


if __name__ == "__main__":
    machines = {
        "memoryless (k=1)": ([[0, 0]], 0, 1),
        "order-1 Markov (k=2)": ([[0, 1], [0, 1]], 0, 2),
        "parity (k=2)": ([[0, 1], [1, 0]], 0, 2),
        "3-cycle (k=3)": ([[1, 1], [2, 2], [0, 0]], 0, 3),
    }
    print(f"{'machine':<24}{'n':>3}{'S_n':>12}{'log S_n':>10}"
          f"{'2k log(n+1)':>14}{'min Hhat':>10}{'max Hhat':>10}{'n log 2':>10}")
    for name, (step, init, k) in machines.items():
        for n in (6, 10, 12):
            z = partition_function(step, init, n)
            hs = [empirical_entropy(step, init, x) for x in all_words(n)]
            print(f"{name:<24}{n:>3}{z:>12.5f}{math.log(z):>10.4f}"
                  f"{2 * k * math.log(n + 1):>14.4f}{min(hs):>10.4f}"
                  f"{max(hs):>10.4f}{n * math.log(2):>10.4f}")
            assert math.log(z) <= 2 * k * math.log(n + 1) + 1e-9
            assert -1e-12 <= min(hs) and max(hs) <= n * math.log(2) + 1e-9
    print("\nEvery instance satisfies the Kraft-type inequality and 0 <= Hhat <= n log 2.")
